<?php
declare(strict_types=1);
require_once dirname(__DIR__).'/core/Update/OperationFiles.php';
foreach(['WorkspaceUrls','RichBlocks','Markdown','PageTree','BookStore','ImportFiles','MintlifyImport','MintlifyMdx','DocusaurusImport','DocusaurusMdx','MarkdownImport'] as $name)require_once dirname(__DIR__).'/src/'.$name.'.php';
use CajeerBook\{DocusaurusImport,DocusaurusMdx,RichBlocks,MarkdownImport};
function check110(bool $okay,string $message):void{if(!$okay)throw new RuntimeException($message);echo "PASS $message\n";}
function reject110(callable $fn,string $message):void{try{$fn();}catch(InvalidArgumentException|DomainException){check110(true,$message);return;}throw new RuntimeException('Expected rejection: '.$message);}
$root=sys_get_temp_dir().'/book-docusaurus-'.bin2hex(random_bytes(8));mkdir($root,0700);$files=[];
try{
    $data=[
        'docusaurus.config.js'=>"module.exports = {title: 'Demo',};",
        'sidebars.js'=>"/** comments */\nconst sidebars = { tutorial: ['intro', {type: 'category', label: 'Tutorials', items: ['guides/start']}, {type:'autogenerated', dirName: 'advanced'}] };\nexport default sidebars;",
        'versions.json'=>json_encode(['1.1'],JSON_THROW_ON_ERROR),
        'versioned_sidebars/version-1.1-sidebars.json'=>json_encode(['tutorial'=>[['type'=>'category','label'=>'Old guides','items'=>['intro','guides/start']]]],JSON_THROW_ON_ERROR),
        'docs/intro.mdx'=>"---\nid: intro\ntitle: Welcome\n---\n# Welcome\n\n[Next](./guides/start.mdx)\n\n![Logo](/img/logo.png)\n",
        'docs/guides/start.mdx'=>"---\nid: start\nsidebar_position: 2\n---\n# Start\n\n:::tip[Notice]\nHello **world**\n:::\n\n<Tabs><TabItem value=\"one\" label=\"First\">First body</TabItem></Tabs>\n",
        'docs/advanced/tricks.md'=>"# Tricks\n",
        'versioned_docs/version-1.1/intro.md'=>"# Old Welcome\n",
        'versioned_docs/version-1.1/guides/start.md'=>"# Old Start\n",
        'i18n/ru/docusaurus-plugin-content-docs/current/intro.mdx'=>"---\ntitle: Приветствие\n---\n# Привет\n",
        'static/img/logo.png'=>base64_decode('iVBORw0KGgoAAAANSUhEUgAAAAEAAAABCAYAAAAfFcSJAAAADUlEQVR4nGP4z8DwHwAFAAH/iZk9HQAAAABJRU5ErkJggg==',true),
    ];
    foreach($data as $name=>$content){$dest=$root.'/'.count($files);file_put_contents($dest,$content);$files['source/'.$name]=$dest;}
    $prepared=DocusaurusImport::prepare($files,'2.0');
    check110($prepared['docusaurus']&&count($prepared['pages'])===6&&isset($prepared['files']['docs/intro.mdx']),'repository wrapper, pages and assets detected');
    check110($prepared['pages']['docs/intro.mdx']['version']==='2.0'&&$prepared['pages']['versioned_docs/version-1.1/intro.md']['version']==='1.1','versioned documentation mapped to distinct Book versions');
    check110($prepared['pages']['i18n/ru/docusaurus-plugin-content-docs/current/intro.mdx']['locale']==='ru'&&$prepared['pages']['i18n/ru/docusaurus-plugin-content-docs/current/intro.mdx']['route']==='ru/intro','Russian translation mapped to independent localized route');
    check110($prepared['nav']['docs/intro.mdx']['order']===10&&$prepared['nav']['docs/guides/start.mdx']['section']==='Tutorials'&&$prepared['nav']['docs/advanced/tricks.md']['order']===30,'static JS sidebar navigation and autogenerated sections');
    check110($prepared['nav']['versioned_docs/version-1.1/intro.md']['section']==='Old guides'&&$prepared['nav']['i18n/ru/docusaurus-plugin-content-docs/current/intro.mdx']['order']===10,'versioned JSON sidebar and localized navigation');
    $warnings=[];$input="import Tabs from '@theme/Tabs';\nimport TabItem from '@theme/TabItem';\n\n:::warning[Watch out]\nSome text\n:::\n\n<Tabs><TabItem value=\"js\" label=\"JavaScript\">Content</TabItem></Tabs>\n";
    $converted=DocusaurusMdx::convert($input,$warnings);
    check110(str_contains($converted,'```book-callout')&&str_contains($converted,'```book-tabs')&&!str_contains($converted,'import Tabs'),'static Docusaurus MDX tabs and admonitions become renderable rich blocks');
    preg_match_all('/```(book-[a-z-]+)\n(.*?)\n```/s',$converted,$matches,PREG_SET_ORDER);foreach($matches as $match)check110(RichBlocks::parse($match[1],$match[2])!==null,'converted '. $match[1] .' block validates');
    $warnings=[];$snippet=DocusaurusMdx::convert("```jsx\n:::tip\nimport Tabs from '@theme/Tabs';\n```\n\n:::note\nNormal content\n:::\n",$warnings);
    check110(str_contains($snippet,'```jsx')&&str_contains($snippet,':::tip')&&str_contains($snippet,'```book-callout'),'fenced code ignored by admonition parser');
    reject110(fn()=>DocusaurusMdx::convert(":::tip\nNever closed\n",$warnings),'unbalanced admonitions rejected');
    reject110(fn()=>DocusaurusMdx::convert("import Evil from './evil';",$warnings),'executable JS import rejected');
    $evil=$root.'/evil';file_put_contents($evil,"const sidebars = { tutorial: [getDocs()] }; export default sidebars;");
    reject110(fn()=>DocusaurusImport::prepare(['sidebars.js'=>$evil,'docs/intro.md'=>$files['source/docs/intro.mdx']],'2.0'),'dynamic sidebar JS rejected without execution');
    $ignored=[];$rewrite=MarkdownImport::rewrite('[Start](./guides/start.mdx) ![Logo](/img/logo.png)','docs/intro.mdx',['docs/guides/start.mdx'=>'guide/2.0/guides/start'],['img/logo.png'=>str_repeat('a',32)],$ignored,[]);
    check110(str_contains($rewrite,'/docs/guide/2.0/guides/start')&&str_contains($rewrite,'/media/'.str_repeat('a',32)),'relative Docusaurus links and static assets rewrite to Book paths');
    echo "Docusaurus 1.0.10 policy tests passed.\n";
}finally{foreach($files as $file)@unlink($file);@unlink($root.'/evil');@rmdir($root);}
